def _format_parameters(self, parameters):
    if not isinstance(parameters, dict):
        raise TypeError('"parameters" must be a dictionary.')
    new_parameters = parameters.copy()
    new_parameters, _ = self.parameter_conversion(new_parameters)
    for key in self.source_parameter_keys.symmetric_difference(
            new_parameters):
        new_parameters.pop(key)
    new_parameters.update(self.waveform_arguments)
    return new_parameters

def _parameters_from_source_model(self):
    """
    Infer the named arguments of the source model.

    Returns
    =======
    set: The names of the arguments of the source model.
    """
    if self.frequency_domain_source_model is not None:
        model = self.frequency_domain_source_model
    elif self.time_domain_source_model is not None:
        model = self.time_domain_source_model
    else:
        raise AttributeError('Either time or frequency domain source '
                             'model must be provided.')
    return set(utils.infer_parameters_from_function(model))

def log_likelihood_ratio(self, parameters=None):
    if parameters is not None:
        parameters = copy.deepcopy(parameters)
    else:
        parameters = _fallback_to_parameters(self, parameters)
    waveform_polarizations = \
        self.waveform_generator.frequency_domain_strain(parameters)
    if waveform_polarizations is None:
        return np.nan_to_num(-np.inf)

    if self.time_marginalization and self.jitter_time:
        parameters['geocent_time'] += parameters['time_jitter']

    parameters.update(self.get_sky_frame_parameters(parameters))

    total_snrs = self._CalculatedSNRs()

    for interferometer in self.interferometers:
        per_detector_snr = self.calculate_snrs(
            waveform_polarizations=waveform_polarizations,
            interferometer=interferometer,
            parameters=parameters,
        )

        total_snrs += per_detector_snr

    log_l = self.compute_log_likelihood_from_snrs(total_snrs, parameters=parameters)

    if self.time_marginalization and self.jitter_time:
        parameters['geocent_time'] -= parameters['time_jitter']

    return float(log_l.real)

def _translate_kwargs(self, kwargs):
    kwargs = super()._translate_kwargs(kwargs)
    if "nlive" not in kwargs:
        for equiv in self.npoints_equiv_kwargs:
            if equiv in kwargs:
                kwargs["nlive"] = kwargs.pop(equiv)
    if "print_progress" not in kwargs:
        if "verbose" in kwargs:
            kwargs["print_progress"] = kwargs.pop("verbose")
    if "walks" not in kwargs:
        for equiv in self.walks_equiv_kwargs:
            if equiv in kwargs:
                kwargs["walks"] = kwargs.pop(equiv)
    if "queue_size" not in kwargs:
        for equiv in self.npool_equiv_kwargs:
            if equiv in kwargs:
                kwargs["queue_size"] = kwargs.pop(equiv)
    if "seed" in kwargs:
        seed = kwargs.get("seed")
        if "rstate" not in kwargs:
            kwargs["rstate"] = np.random.default_rng(seed)
        else:
            logger.warning(
                "Kwargs contain both 'rstate' and 'seed', ignoring 'seed'."
            )

def finalize_sampler_kwargs(self, sampler_kwargs):
    sampler_kwargs["maxcall"] = self.n_check_point
    sampler_kwargs["add_live"] = False

def _translate_kwargs(self, kwargs):
    """Translate keyword arguments.

    Default only translates the sampling seed if the sampler has
    :code:`sampling_seed_key` set.
    """
    if self.sampling_seed_key and self.sampling_seed_key not in kwargs:
        for equiv in self.sampling_seed_equiv_kwargs:
            if equiv in kwargs:
                kwargs[self.sampling_seed_key] = kwargs.pop(equiv)
                set_seed(kwargs[self.sampling_seed_key])
    return kwargs

def frequency_domain_strain(self, frequency_domain_strain):
    if not len(self.frequency_array) == len(frequency_domain_strain):
        raise ValueError("The frequency_array and the set strain have different lengths")
    self._frequency_domain_strain = frequency_domain_strain
    self._time_domain_strain = None
